import { useEffect, useLayoutEffect, useState } from 'react';

import { ChartLegendOrientation } from '../../../../types/legend.js';
import { Variant } from '../types/range-legend.internal.js';
import { RangeItem } from '../types/range-legend.js';
import { getCollisionDetails } from '../utils/get-collision-details.js';
import { getSymmetricPairIndex } from '../utils/get-symmetric-pair-index.js';
import { getVariantMetadata } from '../utils/labels-collision.utils.js';

export const useLabelsVisibilityMap = (
  items: RangeItem[],
  labelsRef: SVGTextElement[],
  orientation: ChartLegendOrientation,
  variant: Variant,
) => {
  const [hiddenLabels, setHiddenLabels] = useState<Set<number>>(
    new Set<number>(),
  );

  const { anchorItems, numberOfItems, semiAnchorItems } = getVariantMetadata(
    items,
    variant,
  );

  const symmetricVariant = variant !== 'ranged';

  useEffect(
    () =>
      setHiddenLabels((prev) => {
        prev.clear();

        return prev;
      }),
    [items],
  );

  useLayoutEffect(() => {
    const elementsClientRect = labelsRef
      .slice(0, numberOfItems + 1)
      .map((el) => el.getBoundingClientRect());

    elementsClientRect.forEach((el: DOMRect, index: number) => {
      const isAnchorElement = anchorItems.includes(index);

      if (!isAnchorElement) {
        setHiddenLabels((prev) => {
          const isSemiAnchorLabel = semiAnchorItems.includes(index);
          const symmetricPairIndex = getSymmetricPairIndex(
            index,
            numberOfItems,
          );
          const isImmediatePair = Math.abs(index - symmetricPairIndex) === 1;
          const applySymmetricLogic = symmetricVariant && !isImmediatePair;

          const hasLeftAndRightLabelsHidden =
            hiddenLabels.has(index - 1) && hiddenLabels.has(index + 1);

          const { hasCollision, hasAnchorCollision } = getCollisionDetails(
            index,
            symmetricPairIndex,
            elementsClientRect,
            numberOfItems,
            orientation,
            symmetricVariant,
          );

          if (hasCollision) {
            // check if the left and right labels of a semi-anchor are hidden in order to implement
            // the UX requirement of priorizing the hiding of the labels next to anchors
            // and keep the middle ones (semi-anchored) visible until there is
            // a collision with an anchor (bound)
            if (
              !isSemiAnchorLabel ||
              (hasLeftAndRightLabelsHidden && hasAnchorCollision)
            ) {
              prev.add(index);
              applySymmetricLogic && prev.add(symmetricPairIndex);
            } else if (
              isSemiAnchorLabel &&
              hasLeftAndRightLabelsHidden &&
              !hasAnchorCollision
            ) {
              prev.delete(index);
              applySymmetricLogic && prev.delete(symmetricPairIndex);
            }
          } else {
            prev.delete(index);
            symmetricVariant && prev.delete(symmetricPairIndex);
          }

          return prev;
        });
      }
    });
  }, [
    anchorItems,
    hiddenLabels,
    labelsRef,
    numberOfItems,
    orientation,
    semiAnchorItems,
    symmetricVariant,
  ]);

  return hiddenLabels;
};
